import sys

def construct_magic_grid(n):
    grid = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            grid[i][j] = (i * n + j) ^ ((i // 2) ^ (j // 2))
    return grid

def main():
    import sys
    n = int(sys.stdin.read().strip())
    grid = construct_magic_grid(n)
    for row in grid:
        print(" ".join(map(str, row)))

main()
